  `season_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'e.g., 2025-2026 Bus Season',
  `depot_name` enum('Kilinochchi','Vavuniya','PointPedro','Kondavil') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `route_from` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `route_to` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `change_point` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
