--
-- Trigger to log deleted student details
--
DROP TRIGGER IF EXISTS `LOG_DELETED_STUDENT`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` TRIGGER `LOG_DELETED_STUDENT`
BEFORE DELETE ON `student`
FOR EACH ROW
BEGIN
    `student_id`,
    `student_fullname`,
    `student_email`,
    `student_nic`,
    `student_gender`,
    `student_status`,
    `deleted_at`
  ) VALUES (
    OLD.`student_id`,
    OLD.`student_fullname`,
    OLD.`student_email`,
    OLD.`student_nic`,
    OLD.`student_gender`,
    OLD.`student_status`,
    NOW()
  );
END ;;
DELIMITER ;

DROP TRIGGER IF EXISTS `student_status_insert`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` TRIGGER `student_status_insert` AFTER INSERT ON `student_enroll` FOR EACH ROW BEGIN
  IF NEW.student_enroll_status IN ('Long Absent','Dropout') THEN
    UPDATE student SET student_status='Inactive' WHERE student_id=NEW.student_id;
  ELSE
    UPDATE student SET student_status='Active'   WHERE student_id=NEW.student_id;
  END IF;
END ;;
DELIMITER ;

DROP TRIGGER IF EXISTS `student_status`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` TRIGGER `student_status` AFTER UPDATE ON `student_enroll` FOR EACH ROW BEGIN
  IF NEW.student_enroll_status IN ('Long Absent','Dropout') THEN
    UPDATE student
      SET student_status = 'Inactive'
      WHERE student_id = NEW.student_id;
  ELSEIF NEW.student_enroll_status IN ('Following','Completed') THEN
    UPDATE student
      SET student_status = 'Active'
      WHERE student_id = NEW.student_id;
  END IF;
END ;;
DELIMITER ;

